 "content": "from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Infer the diagonal wallpaper cycle from the visible interior.  The framed
    # border is separate; wallpaper cells advance by one phase per row/column.
    best = None
    for period in range(2, 11):
        buckets = defaultdict(Counter)
        total = 0
        for r in range(3, h):
            for c in range(3, w):
                v = grid[r][c]
                if v != 0:
                    buckets[(r + c) % period][v] += 1
                    total += 1
        mapping = {phase: counts.most_common(1)[0][0] for phase, counts in buckets.items()}
        correct = sum(counts[mapping[phase]] for phase, counts in buckets.items())
        # Prefer the simplest cycle unless a longer period explains substantially
        # more evidence; ties favor shorter periods.
        score = correct / max(total, 1) - 0.003 * period
        if best is None or score > best[0]:
            best = (score, period, mapping)
    _, period, mapping = best

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = mapping[(r + c) % period]
    return out


if __name__ == '__main__':
    pass

